function writeAll(writable, chunks, done) {
  let i = 0;
  (function next() {
    let ok = true;
    while (i < chunks.length && ok) {
      ok = writable.write(chunks[i++]);
    }
    if (i < chunks.length) writable.once('drain', next); // wait for buffer to clear
    else done();
  })();
}

